<?php declare(strict_types=1);
require __DIR__.'/balance-own-movement-journals.php';
$currency=static fn(int$cents):string=>number_format($cents/100,2,',','');
$ownCase=static function(string$case,int$bankOpening,int$counterOpening,string$counterKind)use($db,$currency):array{
 $club='own-'.$case;$actor=$club.'-board';$db->prepare('INSERT INTO clubs VALUES(?,?)')->execute([$club,'Own actual '.$case]);$db->prepare("INSERT INTO actors(id,club_id,role,is_superuser)VALUES(?,?,'treasurer',1)")->execute([$actor,$club]);$db->prepare("INSERT INTO club_settings(club_id,section,payload,version,updated_at)VALUES(?,'tax',?,1,UTC_TIMESTAMP())")->execute([$club,json_encode(array_replace(Kulturhus\Verein\SettingsSchema::defaults('tax'),['accounting_basis'=>'balance','input_tax_eligibility'=>'no','fiscal_start'=>'2025-07-01']),JSON_THROW_ON_ERROR)]);$finance=new Kulturhus\Verein\Finance($db,$actor);$bank=$finance->createAccount('Own '.$case.' bank','offline',$currency($bankOpening),'2025-07-01');$counter=$finance->createAccount('Own '.$case.' counter',$counterKind,$currency($counterOpening),'2025-07-01');$ledger=new Kulturhus\Verein\BalancePeriodLedger($db,$actor);$period=['start'=>'2025-07-01','end'=>'2026-06-30'];$id=$ledger->create($period,'Own real '.$case.' period',true);$bankAccount='src_bank_'.substr(hash('sha256',$bank),0,20);$counterAccount='src_bank_'.substr(hash('sha256',$counter),0,20);$opening=[];foreach([$bankAccount=>$bankOpening,$counterAccount=>$counterOpening]as$account=>$amount)if($amount)$opening[]=['account'=>$account,'debit_cents'=>$amount,'credit_cents'=>0,'sphere'=>''];$opening[]=['account'=>'equity','debit_cents'=>0,'credit_cents'=>$bankOpening+$counterOpening,'sphere'=>''];$ledger->setup($id,1,$opening,'Own actual reviewed '.$case.' opening',true);return compact('club','actor','finance','bank','counter','ledger','period','id','bankAccount','counterAccount');
};
$postSource=static function(array$case,string$type,string$source,array$options=[])use($db):void{$p=(new Kulturhus\Verein\BalancePeriodSources($db,$case['actor']))->preview($case['period'],$type,$source,$options);check($p['issues']===[],'actual '.$case['club'].' source is freshly and fully evidenced');$r=$case['ledger']->report($case['id']);$case['ledger']->importSource($case['id'],$r['version'],$type,$source,$options,$p['hash'],true);};
$deposit=$ownCase('cash-deposit',10000,10000,'cash');$source=$deposit['finance']->createTransaction(['account'=>$deposit['bank'],'direction'=>'income','amount'=>'50,00','booked_on'=>'2025-09-01','description'=>'Own actual deposit credited'],hash('md5','Own actual deposit bank'));$deposit['finance']->recordCashMovement($source,1,$deposit['counter'],'2025-09-01','50,00','Own actual cash paid into bank',hash('md5','Own actual deposit cash'));$other=$deposit['finance']->internalMovements($source)[0]['outgoing_id'];foreach([$source,$other]as$tx)$postSource($deposit,'transaction',$tx);$r=$deposit['ledger']->report($deposit['id']);check($r['calculation']['annual_result_cents']===0&&$r['calculation']['asset_total_cents']===20000&&$r['calculation']['accounts'][$deposit['bankAccount']]['closing_cents']===15000&&$r['calculation']['accounts'][$deposit['counterAccount']]['closing_cents']===5000,'actual50.00 cash deposit increases bank and reduces cash without income');$deposit['ledger']->close($deposit['id'],$r['version'],$r['journal_sha256'],$checks,'Own actually reconciled deposit closing');check($deposit['ledger']->report($deposit['id'])['state']==='closed','actual cash deposit closes only after both original legs');
$transfer=$ownCase('bank-transfer',10000,0,'offline');$out=$transfer['finance']->createTransaction(['account'=>$transfer['bank'],'direction'=>'expense','amount'=>'20','booked_on'=>'2025-09-01','description'=>'Own actual outgoing bank'],hash('md5','Own actual first bank'));$in=$transfer['finance']->createTransaction(['account'=>$transfer['counter'],'direction'=>'income','amount'=>'20','booked_on'=>'2025-09-01','description'=>'Own actual incoming bank'],hash('md5','Own actual second bank'));$transfer['finance']->linkInternalMovement($out,1,$in,1,'20','Own actual bank to bank classification',hash('md5','Own actual paired banks'));foreach([$in,$out]as$tx)$postSource($transfer,'transaction',$tx);$r=$transfer['ledger']->report($transfer['id']);check($r['calculation']['annual_result_cents']===0&&$r['calculation']['asset_total_cents']===10000&&$r['calculation']['accounts'][$transfer['bankAccount']]['closing_cents']===8000&&$r['calculation']['accounts'][$transfer['counterAccount']]['closing_cents']===2000,'actual own bank transfer imports in reverse order without duplicate money');$transfer['ledger']->close($transfer['id'],$r['version'],$r['journal_sha256'],$checks,'Own real bank transfer closing');check($transfer['ledger']->report($transfer['id'])['state']==='closed','actual own bank transfer has complete original closing');
$fee=$ownCase('withdrawal-fee',100000,10000,'cash');$entry=$fee['finance']->createEntry(['kind'=>'expense','description'=>'Own actual3.00 withdrawal fee','amount'=>'3','document_date'=>'2025-09-01','due_date'=>'2025-09-01','category'=>'general','positions'=>[['description'=>'Own actual documented bank fee','amount'=>'3','tax_rate'=>'0','sphere'=>'1','account'=>'68150','input_tax'=>'none']]],hash('md5','Own actual fee receipt'));(new Kulturhus\Verein\Documents($db,$fee['actor']))->upload('fee-original.png',base64_decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+jRZkAAAAASUVORK5CYII='),['title'=>'Own actual original fee evidence','kind'=>'invoice','scope'=>'finance','links'=>['entry:'.$entry]],hash('md5','Own actual fee original'));$out=$fee['finance']->createTransaction(['account'=>$fee['bank'],'direction'=>'expense','amount'=>'103','booked_on'=>'2025-09-01','description'=>'Own actual withdrawal100 and fee3'],hash('md5','Own actual fee bank'));$in=$fee['finance']->createTransaction(['account'=>$fee['counter'],'direction'=>'income','amount'=>'100','booked_on'=>'2025-09-01','description'=>'Own actual100 cash received'],hash('md5','Own actual fee cash'));$fee['finance']->linkInternalMovement($out,1,$in,1,'100','Own actual cash100 part',hash('md5','Own actual neutral100'));$proposal=(new Kulturhus\Verein\BalancePeriodSources($db,$fee['actor']))->preview($fee['period'],'transaction',$out);check((bool)$proposal['issues'],'actual unallocated3.00 fee still blocks the mixed103.00 bank source');$fee['finance']->allocate($out,(int)$fee['finance']->transactionDetail($out)['version'],$entry,(int)$fee['finance']->entry($entry)['version'],'3',hash('md5','Own actual fee3 allocation'));$postSource($fee,'invoice',$entry,['recognised_on'=>'2025-09-01','private_paid_on'=>'']);foreach([$out,$in]as$tx)$postSource($fee,'transaction',$tx);$r=$fee['ledger']->report($fee['id']);check($r['calculation']['annual_result_cents']===-300&&$r['calculation']['asset_total_cents']===109700&&$r['calculation']['accounts'][$fee['bankAccount']]['closing_cents']===89700&&$r['calculation']['accounts'][$fee['counterAccount']]['closing_cents']===20000,'actual100.00 cash transfer plus3.00 fee creates exactly3.00 loss and1097.00 assets');$fee['ledger']->close($fee['id'],$r['version'],$r['journal_sha256'],$checks,'Own real mixed cash and fee closing');check($fee['ledger']->report($fee['id'])['state']==='closed','actual mixed withdrawal and separate original fee close without duplicate expense');
echo$n.' actual own movement, deposit, fee and journal assertions passed'.PHP_EOL;
